import{_ as n,a0 as r,w as s,s as u,I as a,x as p,a1 as l,A as o,ao as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const v=JSON.parse('{"title":"如何在 Ubuntu server 中设置 RainLoop Webmail | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu server 中设置 RainLoop Webmail | LCTT (201404) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu server 中设置 RainLoop Webmail | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu server 中设置 RainLoop Webmail | LCTT (201404) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201404/How to set up RainLoop webmail in Ubuntu server","title":"如何在 Ubuntu server 中设置 RainLoop Webmail","tag":"201404","desc":""},"relativePath":"201404/How to set up RainLoop webmail in Ubuntu server.md","filePath":"[post].md"}'),m={name:"201404/How to set up RainLoop webmail in Ubuntu server.md"};function d(b,t,f,w,L,T){const e=r("Link");return s(),u("div",null,[t[22]||(t[22]=a("h1",{id:"如何在-ubuntu-server-中设置-rainloop-webmail",tabindex:"-1"},[p("如何在 Ubuntu server 中设置 RainLoop Webmail "),a("a",{class:"header-anchor",href:"#如何在-ubuntu-server-中设置-rainloop-webmail","aria-label":"Permalink to “如何在 Ubuntu server 中设置 RainLoop Webmail”"},"​")],-1)),t[23]||(t[23]=a("p",null,"Webmail无疑是任何邮件服务器必不可少的一部分。虽然本地邮件客户端通常比Webmail的功能更多，但通过电子邮件客户端从外部可信的网络访问IMAP或SMTP有时会很棘手。再者，当你需要在一个特定的工作站、笔记本电脑或者移动设备去使用一个电子邮件客户端时，你可以在任何地方使用Webmail服务，只要你接入互联网。",-1)),a("p",null,[t[1]||(t[1]=p("本教程的重点是在一个运行 Apache 的 Ubuntu 服务器上安装配置",-1)),l(e,{href:"http://rainloop.net/"},{default:o(()=>[...t[0]||(t[0]=[p("RainLoop",-1)])]),_:1}),t[2]||(t[2]=p(" Webmail。RainLoop 是基于 PHP 的Webmail，并且有以下功能。",-1))]),t[24]||(t[24]=i(`<ul><li>支持apache，nginx和其它网页服务器。</li><li>标准接口补充了一个主题库可供选择。</li><li>个人和非盈利项目可免费使用。</li></ul><p>在写这篇文章时，RainLoop 还不支持邮件过滤和不在公司时的自动回复。</p><h3 id="在-ubuntu-服务器上安装-rainloop" tabindex="-1">在 Ubuntu 服务器上安装 RainLoop <a class="header-anchor" href="#在-ubuntu-服务器上安装-rainloop" aria-label="Permalink to “在 Ubuntu 服务器上安装 RainLoop”">​</a></h3><p>首先，在服务器上设置必备的软件包。</p><pre><code># apt-get install wget unzip apache2 php5 php5-mysql libmysqlclient15-dev mysql-server poppassd 
</code></pre><p>接下来，下载和安装 RainLoop。</p><pre><code># mkdir /var/www/webmail
# cd /var/www/webmail
# wget http://repository.Rainloop.net/v1/Rainloop-1.6.3.706-e3c14e17bc4370a1561bcc68d1d494fd.zip
# unzip Rainloop-1.6.3.706-e3c14e17bc4370a1561bcc68d1d494fd.zip
# rm Rainloop-*.zip 
</code></pre><p>然后设置必要的权限。</p><pre><code># cd /var/www/webmail
# find . -type d -exec chmod 755 {} \\;
# find . -type f -exec chmod 644 {} \\;
# chown –R www-data:www-data /var/www/webmail 
</code></pre><p>我们马上就可以使用 RainLoop 了。最后，通过管理面板进行调整，接下来会有详细描述。</p><h3 id="通过管理面板首次配置" tabindex="-1">通过管理面板首次配置 <a class="header-anchor" href="#通过管理面板首次配置" aria-label="Permalink to “通过管理面板首次配置”">​</a></h3><p>很多配置参数通过一款界面友好的管理面板就能调整。使用以下凭证进入管理面板。</p>`,12)),a("ol",null,[a("li",null,[t[4]||(t[4]=p("URL: ",-1)),l(e,{href:"http://IP/webmail/?admin"},{default:o(()=>[...t[3]||(t[3]=[p("http://IP/webmail/?admin",-1)])]),_:1})]),t[5]||(t[5]=a("li",null,"user: admin",-1)),t[6]||(t[6]=a("li",null,"Pass: 12345",-1))]),t[25]||(t[25]=i(`<p>当然，建议尽快修改默认密码。我们将使用管理面板去调整一下设置。</p><h3 id="增加邮件域" tabindex="-1">增加邮件域 <a class="header-anchor" href="#增加邮件域" aria-label="Permalink to “增加邮件域”">​</a></h3><p>在 管理面板&gt; 域&gt; 增加域 页面设置有效的域。建议服务器 IP 是本地服务器，如 127.0.0.1。基于服务器配置，RainLoop 可以配置使用 IMAP/IMAPS 或 SMTP/SMTPS。并且，确认‘使用短登录表单’复选框已勾选。</p><p><img src="http://farm4.staticflickr.com/3736/12603680854_eb22bd8eb8_z.jpg" alt=""></p><p>使用‘测试连接’按钮验证设置。</p><h3 id="启用联系人" tabindex="-1">启用联系人 <a class="header-anchor" href="#启用联系人" aria-label="Permalink to “启用联系人”">​</a></h3><p>联系人功能需要数据库支持。我们将使用 MySQL 数据库启用联系人。RainLoop 可以手动创建所需的数据库，如下。</p><pre><code># mysql -u root -p 

mysqlcreate database rainloop;
mysqlexit;
</code></pre><p>现在这个功能可以通过管理面板&gt;联系人页面启用。</p><p><img src="http://farm8.staticflickr.com/7452/12603262215_2299bdafc5_z.jpg" alt=""></p><p>再来一次，使用‘测试’按钮检查设置。</p><h3 id="启动密码更改插件" tabindex="-1">启动密码更改插件 <a class="header-anchor" href="#启动密码更改插件" aria-label="Permalink to “启动密码更改插件”">​</a></h3><p>在多数 linux 的邮件账户的邮件服务器是用自己的 UID 和 GID 操作系统的实际用户。因此，在过去更改这些账户的密码是很棘手的。幸好，今天有工具可以完成这个工作。这个工具是 poppassd。</p><p>第一步是在服务器上安装 poppassd，可以用 apt-get 来完成。</p><pre><code># apt-get install poppassd 
</code></pre><p>接下来，去允许 RainLoop 使用 poppassd，从 管理面板&gt; 软件包 页面安装 RainLoop 插件 poppassd。</p><p><img src="http://farm4.staticflickr.com/3734/12603357113_a966caf534_z.jpg" alt=""></p><p>最后，poppassd 插件可以从 管理面板&gt; 插件页面启用。</p><p><img src="http://farm8.staticflickr.com/7356/12603681254_56fc0b3e9f_z.jpg" alt=""></p><p>现在所有参数已设置，用户可以从他们提供的凭证登录，如截图所示。</p>`,20)),a("ul",null,[a("li",null,[t[8]||(t[8]=p("URL: ",-1)),l(e,{href:"http://IP/webmail"},{default:o(()=>[...t[7]||(t[7]=[p("http://IP/webmail",-1)])]),_:1})]),t[9]||(t[9]=a("li",null,"user: user@domain",-1)),t[10]||(t[10]=a("li",null,"pass: password",-1))]),t[26]||(t[26]=a("p",null,[a("img",{src:"http://farm4.staticflickr.com/3721/12603357333_724fbddaff_z.jpg",alt:""})],-1)),t[27]||(t[27]=a("p",null,"希望这篇文章能帮助到你。",-1)),t[28]||(t[28]=a("hr",null,null,-1)),a("p",null,[t[12]||(t[12]=p("via: ",-1)),l(e,{href:"http://xmodulo.com/2014/02/rainloop-webmail-ubuntu-server.html"},{default:o(()=>[...t[11]||(t[11]=[p("http://xmodulo.com/2014/02/rainloop-webmail-ubuntu-server.html",-1)])]),_:1})]),a("p",null,[t[15]||(t[15]=p("译者：",-1)),l(e,{href:"https://github.com/vito-L"},{default:o(()=>[...t[13]||(t[13]=[p("Vito",-1)])]),_:1}),t[16]||(t[16]=p(" 校对：",-1)),l(e,{href:"https://github.com/carolinewuyan"},{default:o(()=>[...t[14]||(t[14]=[p("Caroline",-1)])]),_:1})]),a("p",null,[t[19]||(t[19]=p("本文由 ",-1)),l(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[17]||(t[17]=[p("LCTT",-1)])]),_:1}),t[20]||(t[20]=p(" 原创翻译，",-1)),l(e,{href:"http://linux.cn/"},{default:o(()=>[...t[18]||(t[18]=[p("Linux中国",-1)])]),_:1}),t[21]||(t[21]=p(" 荣誉推出",-1))])])}const P=n(m,[["render",d]]);export{v as __pageData,P as default};
